 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('contact-form');
     const statusDiv = document.getElementById('form-status');

     form.addEventListener('submit', (e) => {
         e.preventDefault();

         // Reset styles and messages
         const inputs = form.querySelectorAll('input');
         inputs.forEach(input => input.classList.remove('invalid'));
         statusDiv.textContent = '';
         statusDiv.className = '';

         const fullName = document.getElementById('full-name');
         const email = document.getElementById('email');

         let isValid = true;

         // Simple validation
         if (!fullName.value.trim()) {
             fullName.classList.add('invalid');
             isValid = false;
         }

         if (!email.value.trim() || !validateEmail(email.value)) {
             email.classList.add('invalid');
             isValid = false;
         }

         if (isValid) {
             // Mock success
             statusDiv.textContent = 'Thank you! Your message has been sent.';
             statusDiv.classList.add('success-message');
             form.reset();

             // Focus the status message for accessibility
             statusDiv.setAttribute('tabindex', '-1');
             statusDiv.focus();
         } else {
             statusDiv.textContent = 'Please correct the errors above and try again.';
             statusDiv.classList.add('error-message');

             // Focus first invalid element
             const firstInvalid = form.querySelector('.invalid');
             if (firstInvalid) {
                 firstInvalid.focus();
             }
         }
     });

     function validateEmail(email) {
         const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         return re.test(String(email).toLowerCase());
     }
 });

